// Bounded recovery of managed execution 1172710, not a general retry mechanism.
// Import 724's Direct result was verified before recovery. Preserve import 725.
async function resolveKnownGenericRecovery(body, sheetId, read, now = Date.now()) {
  if (body.topUpLeadListId !== 'rec0dWrkBVCdPQEND') return null;
  const fail = message => { throw new Error('Top-up recovery blocked: ' + message); };
  const auditTime = Date.parse('2026-11-03T14:29:10Z');
  if (!Number.isFinite(now) || now < auditTime || now - auditTime > 2*60*60*1000) fail('membership audit is stale; refresh the complete identity reconciliation.');
  const baseUrl = String(body.baseUrl || '').replace(/\/$/, '');
  if (body.parentRecordId !== 'recaM6Leomumw4auE' || baseUrl !== 'https://send.dulcy.io' || sheetId !== '1BsEBERo9qe330B-ofMIoZszCRl5ci_UxkaqLz_ALMU4') fail('source or provider identity changed.');
  const expectedTargets = [
    'recIbAm41zVwTYyRI|601|generic|3360',
    'recaM6Leomumw4auE|602|direct|1348',
  ].sort();
  const actualTargets = body.targets.map(t => [t.recordId, Number(t.campaignId), t.outputType, Number(t.expectedRows)].join('|')).sort();
  if (JSON.stringify(actualTargets) !== JSON.stringify(expectedTargets)) fail('destination family or source counts changed.');
  const unwrap = response => (response?.body ?? response);
  const direct = unwrap(await read('/api/lead-lists/724'))?.data;
  const generic = unwrap(await read('/api/lead-lists/725'))?.data;
  const exactCount = (value, expected) => value !== null && value !== '' && Number.isSafeInteger(Number(value)) && Number(value) === expected;
  if (!direct || Number(direct.id) !== 724 || direct.status !== 'Processed' || !exactCount(direct.leads_processed,1348) || !exactCount(direct.leads_succeeded,1348) || !exactCount(direct.leads_failed,0)) fail('Direct import 724 no longer matches its completed receipt; do not reupload Direct.');
  if (!generic || Number(generic.id) !== 725 || generic.status !== 'Processed' || !exactCount(generic.leads_processed,3160) || !exactCount(generic.leads_succeeded,0) || !exactCount(generic.leads_failed,3160)) fail('Generic import 725 changed; reconcile that import before another upload.');
  const prefix = String(body.topUpLeadListName) + ' - ';
  if (direct.name !== prefix+'direct - Top Up 2026-11-03' || generic.name !== prefix+'generic - Top Up 2026-11-03') fail('provider import names do not match this exact source list.');
  if (!Object.prototype.hasOwnProperty.call(generic.error_messages ?? {},'First name is a required field')) fail('Generic import failure changed.');
  // Any other Generic import for this source, even Unprocessed/failed, is an
  // uncertain or completed prior recovery. Preserve it; never blindly reupload.
  let lastPage = 1, expectedTotal = null;
  const seen = new Set();
  for (let page=1;page<=lastPage;page++) {
    const response = unwrap(await read('/api/lead-lists',{page}));
    if (!Array.isArray(response?.data)) fail('incomplete provider import history.');
    const meta = response.meta ?? {};
    if (!Number.isSafeInteger(Number(meta.last_page)) || Number(meta.last_page)<1 || Number(meta.last_page)>100 || Number(meta.current_page)!==page || !Number.isSafeInteger(Number(meta.total))) fail('invalid provider import pagination.');
    if (expectedTotal === null) { expectedTotal=Number(meta.total); lastPage=Number(meta.last_page); }
    if (Number(meta.total)!==expectedTotal || Number(meta.last_page)!==lastPage) fail('provider import history changed during recovery preflight.');
    for(const list of response.data){
      if(!Number.isSafeInteger(Number(list.id)) || seen.has(Number(list.id))) fail('duplicate or missing import identity.');
      seen.add(Number(list.id));
      if(Number(list.id)!==725 && String(list.name??'').startsWith(prefix+'generic - Top Up ')) fail('existing Generic import '+list.id+' must be reconciled; no new upload was started.');
    }
  }
  if(seen.size!==expectedTotal || !seen.has(724) || !seen.has(725)) fail('incomplete provider import history coverage.');
  const campaign = unwrap(await read('/api/campaigns/601/leads',{page:1}));
  if(!exactCount(campaign?.meta?.total,7590)) fail('Generic campaign membership count changed from the complete 7,590-lead audit.');
  return {
    recoveryId:'execution-1172710-generic-first-name',
    failedImportId:725,
    providerCounterShortfall:200,
    membershipAudit:{campaignId:601,total:7590,sourceRows:3360,sourceOverlap:0,auditedAt:'2026-11-03T14:29:10Z'},
    preservedResults:[{
      outputType:'direct',campaignName:'direct destination',campaignId:602,leadListId:724,
      acceptedRows:1348,added:1345,skipped:3,failed:0,
      countBasis:'preserved-verified-result-from-managed-execution-1172710',
      providerImport:{id:724,status:'Processed',processed:1348,succeeded:1348,failed:0},
      attachmentReceipt:{success:true,campaignId:602,leadListId:724},beforeTotal:2075,afterTotal:3420,
      preservedFromExecution:'1172710',
    }],
  };
}


const body = $json.body ?? $json;
if(!body.uploadPreparation||typeof body.uploadPreparation.uploadId!=='string'||!/^([a-f0-9]{64})$/.test(body.uploadPreparation.revisionHash??''))throw Error('Prepare and select the exact completed top-up in Campaign Center before uploading.');
