for (const key of required) if (!body[key] || (key === 'targets' && !Array.isArray(body[key]))) throw new Error('Missing required top-up value: ' + key);
const match = String(body.projectSheetLink).match(/\/spreadsheets\/d\/([a-zA-Z0-9-_]+)/);
if (!match) throw new Error('The selected lead list does not contain a valid Google Sheet URL.');
if (!/^https:\/\/[^/\s]+\/?$/.test(String(body.baseUrl || ''))) throw new Error('A valid EmailBison HTTPS server is required.');
// All destination outputs form the duplicate-exclusion union, even if one has zero new rows.
const exclusionCampaigns=body.targets.map(t=>({campaignId:Number(t?.campaignId),recordId:String(t?.recordId??''),baseUrl:String(body.baseUrl||'').replace(/\/$/,'')}));
if(exclusionCampaigns.length<1||exclusionCampaigns.length>2||exclusionCampaigns.some(t=>!Number.isSafeInteger(t.campaignId)||t.campaignId<1||!/^rec[A-Za-z0-9]+$/.test(t.recordId)||t.baseUrl!=='https://send.dulcy.io')||new Set(exclusionCampaigns.map(t=>t.campaignId)).size!==exclusionCampaigns.length)throw Error('Upload blocked: invalid or duplicate destination-family targets.');
for(const [key,max]of [['familyRecordIds',3],['readinessRecordIds',100]])if(!Array.isArray(body[key])||!body[key].length||body[key].length>max||body[key].some(id=>!/^rec[A-Za-z0-9]+$/.test(id))||new Set(body[key]).size!==body[key].length)throw Error('Upload blocked: missing or invalid '+key);
const knownRecovery = await resolveKnownGenericRecovery(body, match[1], (path, qs) => this.helpers.httpRequest({timeout:30000,method:'GET',url:String(body.baseUrl).replace(/\/$/,'')+path,headers:{Authorization:'Bearer '+body.apiKey},...(qs?{qs}:{}),json:true}));
const targets = body.targets.filter(target => target?.campaignId && Number(target?.expectedRows || 0) > 0 && (!knownRecovery || target.outputType === 'generic'));
