 const request=expected.r,prefix='https://sheets.googleapis.com/v4/spreadsheets/'+request.sourceSheetId+'/values/';
 if(!String(request.sheetUrl).startsWith(prefix)||decodeURIComponent(String(request.sheetUrl).slice(prefix.length).split('!')[0]).replace(/^'|'$/g,'')!==request.sourceTab)throw Error('Sheets request ID/range mismatch');
 if(data?.error||!Array.isArray(data?.values)||!data.values.length||!Array.isArray(data.values[0])||typeof data.range!=='string'||data.range.split('!')[0].replace(/^'|'$/g,'')!==request.sourceTab)throw Error('Sheets response error/range mismatch');
 if(data.spreadsheetId!=null&&String(data.spreadsheetId)!==request.sourceSheetId)throw Error('Sheets response ID mismatch');
 responseByKey.set(bound.requestKey,{item:downloaded[index],inputIndex:index});
